mapper.select:
select u.id as userId, u.username as username, u.email as email, u.avatar as avatar, latest.member_type as memberType, case latest.member_type when 'vip' then 'VIP Member' when 'small_class' then 'Small Class Member' else latest.member_type end as memberTypeName, latest.plan_name_snapshot as planName, case when latest.expire_time is not null and latest.expire_time > now() then 1 else 0 end as memberActive, date_format(latest.expire_time, '%Y-%m-%d %H:%i:%s') as memberExpireTime, coalesce(course_total.total_course_count, 0) as totalCourseCount, coalesce(progress_summary.started_course_count, 0) as startedCourseCount, coalesce(progress_summary.completed_course_count, 0) as completedCourseCount, case when coalesce(course_total.total_course_count, 0) > 0 then round(coalesce(progress_summary.total_progress_percent, 0) / course_total.total_course_count, 2) else 0.00 end as overallProgress, case when coalesce(course_total.total_course_count, 0) > 0 then round(coalesce(progress_summary.started_course_count, 0) * 100.00 / course_total.total_course_count, 2) else 0.00 end as startRate, case when coalesce(course_total.total_course_count, 0) > 0 then round(coalesce(progress_summary.completed_course_count, 0) * 100.00 / course_total.total_course_count, 2) else 0.00 end as completionRate, date_format(progress_summary.last_learn_time, '%Y-%m-%d %H:%i:%s') as lastLearnTime from osh_user u inner join ( select mo.user_id, mo.member_type, mo.plan_name_snapshot, mo.expire_time from osh_member_order mo inner join ( select user_id, max(id) as max_id from osh_member_order where pay_status = 1 and delete_flag = 0 group by user_id ) latest_order on latest_order.max_id = mo.id ) latest on latest.user_id = u.id left join ( select t.user_id, count(distinct t.course_id) as total_course_count from ( select ocb.user_id, ocb.course_id from osh_course_buy ocb where ocb.pay_status = 'paid' and ocb.delete_flag = 0 union all select agg.user_id, agg.course_id from (
) agg ) t group by t.user_id ) course_total on course_total.user_id = u.id left join ( select agg.user_id, count(1) as started_course_count, sum(coalesce(agg.progress_percent, 0)) as total_progress_percent, sum(case when coalesce(agg.is_completed, 0) = 1 then 1 else 0 end) as completed_course_count, max(agg.last_learn_time) as last_learn_time from (
) agg group by agg.user_id ) progress_summary on progress_summary.user_id = u.id where u.delete_flag = 0
and (u.username like concat('%', #{query.keyword}, '%') or u.email like concat('%', #{query.keyword}, '%'))
and latest.member_type = #{query.memberType}
and latest.expire_time is not null and latest.expire_time > now()
order by case when latest.expire_time is not null and latest.expire_time > now() then 1 else 0 end desc, progress_summary.last_learn_time desc, latest.expire_time desc, u.id desc

select u.id as userId, u.username as username, u.email as email, u.avatar as avatar, latest.member_type as memberType, case latest.member_type when 'vip' then 'VIP Member' when 'small_class' then 'Small Class Member' else latest.member_type end as memberTypeName, latest.plan_name_snapshot as planName, case when latest.expire_time is not null and latest.expire_time > now() then 1 else 0 end as memberActive, date_format(latest.expire_time, '%Y-%m-%d %H:%i:%s') as memberExpireTime, coalesce(course_total.total_course_count, 0) as totalCourseCount, coalesce(progress_summary.started_course_count, 0) as startedCourseCount, coalesce(progress_summary.completed_course_count, 0) as completedCourseCount, greatest(coalesce(course_total.total_course_count, 0) - coalesce(progress_summary.started_course_count, 0), 0) as unstartedCourseCount, case when coalesce(course_total.total_course_count, 0) > 0 then round(coalesce(progress_summary.total_progress_percent, 0) / course_total.total_course_count, 2) else 0.00 end as overallProgress, case when coalesce(course_total.total_course_count, 0) > 0 then round(coalesce(progress_summary.started_course_count, 0) * 100.00 / course_total.total_course_count, 2) else 0.00 end as startRate, case when coalesce(course_total.total_course_count, 0) > 0 then round(coalesce(progress_summary.completed_course_count, 0) * 100.00 / course_total.total_course_count, 2) else 0.00 end as completionRate, date_format(progress_summary.first_learn_time, '%Y-%m-%d %H:%i:%s') as firstLearnTime, date_format(progress_summary.last_learn_time, '%Y-%m-%d %H:%i:%s') as lastLearnTime from osh_user u inner join ( select mo.user_id, mo.member_type, mo.plan_name_snapshot, mo.expire_time from osh_member_order mo inner join ( select user_id, max(id) as max_id from osh_member_order where pay_status = 1 and delete_flag = 0 group by user_id ) latest_order on latest_order.max_id = mo.id ) latest on latest.user_id = u.id left join ( select t.user_id, count(distinct t.course_id) as total_course_count from ( select ocb.user_id, ocb.course_id from osh_course_buy ocb where ocb.pay_status = 'paid' and ocb.delete_flag = 0 union all select agg.user_id, agg.course_id from (
) agg ) t group by t.user_id ) course_total on course_total.user_id = u.id left join ( select agg.user_id, count(1) as started_course_count, sum(coalesce(agg.progress_percent, 0)) as total_progress_percent, sum(case when coalesce(agg.is_completed, 0) = 1 then 1 else 0 end) as completed_course_count, min(agg.first_learn_time) as first_learn_time, max(agg.last_learn_time) as last_learn_time from (
) agg group by agg.user_id ) progress_summary on progress_summary.user_id = u.id where u.delete_flag = 0 and u.id = #{userId} limit 1
